{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, a C40 isoprenoid with high transferability, showed 58.5% absolute oral bioavailability in humans, which is contradictory to a low-F prediction but comes from a smaller hydrocarbon without the quinone head.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Lycopene dispersed in oil showed only ~1.2% systemic availability in humans, supporting low oral bioavailability for large lipophilic isoprenoids even when solubilized.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lycopene from tomato paste showed 0.17% systemic availability, further supporting the poor absorption of large carotenoid-type isoprenoids, though food-matrix conditions limit transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A tocotrienol-rich palm oil fraction has poor oral bioavailability, supporting low F for lipophilic isoprenoid natural products with a polar ring head.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A 13C-lycopene study reported 23.2% bioavailability for all-trans lycopene, a contradictory high value, but it is an outlier relative to other lycopene systemic-availability measurements.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin showed high oral bioavailability in volunteers, but its much lower molecular weight and different scaffold limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is coenzyme Q10, an 863 Da polyprenyl quinone with extreme lipophilicity and no ionizable groups. Although phytoene and one lycopene study show high absorption in humans, those compounds are smaller hydrocarbons/carotenoids; the more consistent lycopene systemic-availability data and tocotrienol evidence, together with the strong physicochemical barriers to dissolution and absorption, support F < 20%. Small-molecule/prodrug high-F records are not applicable.",
  "evidence_gaps": [
    "No direct oral bioavailability record for coenzyme Q10 or ubiquinone analogues was retrieved.",
    "Carotenoid data are complicated by food-matrix and formulation effects; absolute F for the query's pure compound is uncertain.",
    "First-pass metabolism and intestinal efflux of the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

